// frontend/src/App.js
import React, { useState, useEffect } from "react";
import "./App.css";
// Icons
import { Gamepad2, Trophy, Star, Zap, Sparkles, Play } from 'lucide-react';
// Components 
import Dashboard from "./components/Dashboard"; 
import Lesson from "./components/Lesson";
import Quiz from "./components/Quiz";
import Chatbot from "./components/Chatbot";
import Login from "./Login";
import Signup from "./Signup";
import { Routes, Route, useNavigate } from "react-router-dom";

// Keep your existing lesson data
const STEM_LESSONS = [ 
  {
    id: 1,
    title: "Bright Bulbs: Simple Circuits",
    subject: "Science 💡 Electricity",
    content: "Learn how electric current flows...",
    quiz: []
  },
  // ... rest of your lessons
];

export default function App() {
  const [view, setView] = useState("home");
  const [currentLesson, setCurrentLesson] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(!!localStorage.getItem('token'));
  const navigate = useNavigate();

  // Handle "Start Learning" click
  const handleStart = () => {
    if (isLoggedIn) {
      setView("dashboard");
    } else {
      navigate("/login");
    }
  };

  return (
    <div className="app-root">
      
      {/* --- HOME PAGE VIEW --- */}
      {view === "home" && (
        <div className="landing-page">
          
          {/* Navbar */}
          <nav className="navbar">
            <div className="logo">
              <Gamepad2 size={32} /> VidyaQuest
            </div>
            <div className="nav-links">
              <span>Home</span>
              <span>Subjects</span>
              <span>Games</span>
              <span>Leaderboard</span>
            </div>
            <div className="auth-buttons">
              {!isLoggedIn ? (
                <>
                  <button className="btn-nav-login" onClick={() => navigate("/login")}>Sign In</button>
                  <button className="btn-nav-signup" onClick={() => navigate("/signup")}>Sign Up</button>
                </>
              ) : (
                <button className="btn-nav-signup" onClick={() => setView("dashboard")}>Dashboard</button>
              )}
            </div>
          </nav>

          {/* Hero Section */}
          <div className="hero-container">
            
            {/* THE FLOATING ICONS (Matches Image 2) */}
            <div className="floating-icon icon-teal"><Star size={32} strokeWidth={3} /></div>
            <div className="floating-icon icon-orange"><Trophy size={32} strokeWidth={3} /></div>
            <div className="floating-icon icon-blue"><Zap size={32} strokeWidth={3} /></div>
            <div className="floating-icon icon-pink"><Sparkles size={32} strokeWidth={3} /></div>

            {/* Main Text */}
            <div className="badge">✨ For Grades 6-12</div>
            <h1 className="hero-title">
              Learn, Play & <br />
              <span className="highlight">Grow!</span>
            </h1>
            <p className="hero-subtitle">
              Making STEM education fun and accessible for rural students <br />
              with offline-ready gamified lessons.
            </p>
            
            {/* Buttons */}
            <div className="hero-buttons">
              <button className="btn-primary-lg" onClick={handleStart}>
                ✨ Start Learning
              </button>
              <button className="btn-secondary-lg">
                <Play size={18} style={{marginRight:'8px', display:'inline'}}/> Watch Demo
              </button>
            </div>

            {/* Stats Cards */}
            <div className="stats-row">
              <div className="stat-card">
                 <span className="stat-num">10K+</span>
                 <span className="stat-label">Students Learning</span>
              </div>
              <div className="stat-card">
                 <span className="stat-num">500+</span>
                 <span className="stat-label">Lessons Completed</span>
              </div>
              <div className="stat-card">
                 <span className="stat-num">1000+</span>
                 <span className="stat-label">Hours of Content</span>
              </div>
            </div>

          </div>
        </div>
      )}

      {/* --- DASHBOARD VIEW (Existing Logic) --- */}
      {view === "dashboard" && (
         <Dashboard lessons={STEM_LESSONS} onOpen={(l) => {setCurrentLesson(l); setView("lesson")}} />
      )}
      
      {view === "lesson" && currentLesson && (
         <Lesson lesson={currentLesson} onBack={() => setView("dashboard")} onQuiz={() => setView("quiz")} />
      )}

      {view === "quiz" && currentLesson && (
         <Quiz lesson={currentLesson} questions={currentLesson.quiz} onBack={() => setView("lesson")} />
      )}

      {/* Routes for Login/Signup */}
      <Routes>
        <Route path="/login" element={<Login onSuccess={() => { setIsLoggedIn(true); setView("home"); }} />} />
        <Route path="/signup" element={<Signup onSuccess={() => navigate("/login")} />} />
      </Routes>
    </div>
  );
}
